			if (!maker) maker = document.querySelector(".space-y-2 a[href*=\"/makers/\"], a[href*=\"/makers/\"], .space-y-2 a[href*=\"/labels/\"], a[href*=\"/labels/\"]")?.textContent?.trim() || "";
			if (actresses.length === 0) {
				const links = document.querySelectorAll("a[href*=\"/actresses/\"], a[href*=\"/actress/\"]");
				const set = new Set();
				const blocked = new Set([
					"actresses",
					"actress",
					"ranking",
					"saved",
					"collection",
					"list"
				]);
				for (const a of links) {
					const slug = decodeURIComponent(a.pathname.split("/").filter(Boolean).pop()?.toLowerCase() || "");
					if (blocked.has(slug)) continue;
					const name = a.textContent?.trim();
					if (name && name.length >= 2 && !name.includes("/") && !blocked.has(name.toLowerCase())) set.add(name);
				}
				actresses = [...set];
			}
