		if (suaEnabled() && !sua.paused && sua.state.cinema) root.setAttribute("data-sua-cinema", "1");
		else root.removeAttribute("data-sua-cinema");
		if (themed && sua.state.invert) root.setAttribute("data-sua-invert", "1");
		else root.removeAttribute("data-sua-invert");
