	function suaFindVideo() {
		var list = [];
		try {
			list = Array.prototype.slice.call(document.querySelectorAll("video"));
		} catch (error) {
			return null;
		}
		// v6.39.16 同版修五：同源内嵌帧里的视频也找（很多站把播放器放 iframe 里）。
		// 跨域帧读不到（浏览器同源策略），try 里直接跳过，不报错。
		try {
			var frames = document.querySelectorAll("iframe");
			for (var fi = 0; fi < frames.length; fi++) {
				try {
					var fdoc = frames[fi].contentDocument;
					if (!fdoc) continue;
					var fvs = fdoc.querySelectorAll("video");
					for (var vi = 0; vi < fvs.length; vi++) list.push(fvs[vi]);
				} catch (e2) {}
			}
		} catch (error) {}
		var best = null;
		var bestScore = -1;
		for (var i = 0; i < list.length; i++) {
			var el = list[i];
			// v6.24.0：广告视频不参与选主视频（免得字幕/手势挂到广告上）
			try {
				var vsrc = (el.currentSrc || el.src || el.getAttribute("poster") || "");
				if (suaIsAdUrl(vsrc)) continue;
			} catch (error) {}
			var rect = el.getBoundingClientRect();
			var area = rect.width * rect.height;
			if (rect.width > 140 && rect.height > 80) {
				// v6.40.3：只认视口里可见的视频——滚出屏幕的、藏在顶栏广告位的不要。
				var vw3 = window.innerWidth || 0, vh3 = window.innerHeight || 0;
				var visW = Math.max(0, Math.min(rect.right, vw3) - Math.max(rect.left, 0));
				var visH = Math.max(0, Math.min(rect.bottom, vh3) - Math.max(rect.top, 0));
				if (visW < 140 || visH < 80) continue;
				// v6.39.16 同版修七：正在播的面积翻倍——18AV 有 66 个预览 video，
				// 主视频要点播才生成；同尺寸优先取正在播的，大暂停主视频仍赢小播着的预览。
				var playing7 = 0;
				try { playing7 = (!el.paused && Number(el.currentTime) > 0) ? 1 : 0; } catch (e) {}
				var score7 = area * (playing7 ? 2 : 1);
				// v6.40.3：居中加分——主视频一般在屏幕中央，顶栏/边栏的广告视频在边缘。
				var cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
				if (vw3 > 0 && vh3 > 0 && cx > vw3 * 0.2 && cx < vw3 * 0.8 && cy > vh3 * 0.2 && cy < vh3 * 0.8) score7 *= 1.5;
				if (score7 > bestScore) { best = el; bestScore = score7; }
			}
		}
		return best || list[0] || null;
	}
	// v6.40.3：手指点/滑哪个视频，哪个就是主视频——用户摸到的视频才是真理。
	// 之前字幕在顶、左滑右滑没提示，都是 sua.video 抓错了视频（页面顶上有别的
	// video 在播，字幕和手势全挂到它身上，用户滑的是中间的主视频，自然没反应）。
	// 捕获阶段监听，点到视频就切主视频并绑手势、重定位字幕。
	function suaBindTouchPickVideo() {
		if (window.__suaTouchPick__) return;
		window.__suaTouchPick__ = true;
		try {
			document.addEventListener("touchstart", function (ev) {
				try {
					if (sua.state && sua.state.mini) return;
					if (sua.paused || (sua.state && sua.state.screenLock)) return;
					var t = ev && ev.target ? ev.target : null;
					if (!t || !t.closest) return;
					var v = t.closest("video");
					if (!v || !v.isConnected) return;
					try { var vsrc = (v.currentSrc || v.src || ""); if (suaIsAdUrl(vsrc)) return; } catch (e) {}
					var r = v.getBoundingClientRect();
					if (r.width < 140 || r.height < 80) return;
					if (sua.video !== v) {
						sua.video = v;
						try { suaBindGestures(v); } catch (e) {}
						try { suaPositionOverlay(); } catch (e) {}
						try { suaTick(true); } catch (e) {}
					}
				} catch (e) {}
			}, true);
		} catch (error) {}
	}
	function suaHasIframe() {
		try { return document.querySelectorAll("iframe").length > 0; } catch (error) { return false; }
	}
	// v6.39.16 同版修六：跨域内嵌帧的视频搬不出来，改成接力播。
	// 帧里的脚本实例（和主框架同源策略互不干扰，各管各的文档）把视频地址
	// 发给主框架，主框架在小窗里用同一个地址重播，字幕照样盖在上面。
	// blob: 地址发了也没用（只在帧里有效），直接跳过。
	function suaIframeShareVideo() {
		try {
			if (window.self === window.top) return;
			var video = sua.video;
			if (!video || !video.isConnected) { try { video = suaFindVideo(); if (video) sua.video = video; } catch (e) {} }
			if (!video) return;
			var url = "";
			try { url = video.currentSrc || video.src || ""; } catch (e) {}
			if (!url || /^blob:/i.test(url)) {
				try {
					var sources = video.querySelectorAll("source");
					for (var i = 0; i < sources.length; i++) {
						var s = sources[i].src || sources[i].getAttribute("src") || "";
						if (s && !/^blob:/i.test(s)) { url = s; break; }
					}
				} catch (e2) {}
			}
			if (!url || /^blob:/i.test(url) || !/^https?:/i.test(url)) return;
			var msg = { type: "sua-iframe-video", url: url, currentTime: 0, duration: 0, paused: true };
			try { msg.currentTime = Number(video.currentTime) || 0; } catch (e) {}
			try { msg.duration = Number(video.duration) || 0; } catch (e) {}
			try { msg.paused = Boolean(video.paused); } catch (e) {}
			try { window.parent.postMessage(msg, "*"); } catch (e) {}
		} catch (error) {}
	}
	function suaOnIframeVideoMsg(event) {
		try {
			var d = event && event.data;
			if (!d || d.type !== "sua-iframe-video") return;
			var url = String(d.url || "");
			if (!url || /^blob:/i.test(url) || !/^https?:/i.test(url)) return;
			// 只收最新的；正在播的优先（多个帧时不被广告帧顶掉）。
			var prev = sua.iframeVideo;
			if (prev && prev.paused === false && d.paused !== false && Date.now() - (prev.at || 0) < 5000) return;
			sua.iframeVideo = { url: url, currentTime: Number(d.currentTime) || 0, duration: Number(d.duration) || 0, paused: d.paused !== false, at: Date.now() };
		} catch (error) {}
	}
	function suaMiniFromIframe() {
		try {
			var info = sua.iframeVideo;
			if (!info || !info.url) return null;
			if (Date.now() - (info.at || 0) > 30000) return null;
			var v = document.createElement("video");
			v.src = info.url;
			v.controls = true;
			v.playsInline = true;
			v.preload = "metadata";
			v.setAttribute("data-sua-iframe-video", "1");
			try { if (Number(info.currentTime) > 0) v.currentTime = Number(info.currentTime); } catch (e) {}
			sua.iframeVideoEl = v;
			return v;
		} catch (error) { return null; }
	}
	function suaWatchHash() {
		if (!/[#&]sua-watch=1(?:&|$)/.test(String(location.hash || ""))) return false;
		var tries = 0;
		var attach = function () {
			var video = suaFindVideo();
			if (video) {
				sua.video = video;
				try { suaEnsureUi(); } catch (error) {}
				try { suaBindGestures(video); } catch (error) {}
				try { suaApplyAll(); } catch (error) {}
				try { suaQuickbar(); } catch (error) {}
				suaToast("已接管本站播放器；受保护直链交给站点播放最稳");
				return;
			}
			if (tries++ < 30) window.setTimeout(attach, 500);
		};
		attach();
		return true;
	}
	function suaSetImportant(el, prop, value) {
		if (!el) return;
		try {
			if (value === "" || value == null) el.style.removeProperty(prop);
			else el.style.setProperty(prop, value, "important");
		} catch (error) {}
	}
	function suaUnlockWrappers() {
		for (var i = 0; i < sua.unlocked.length; i++) sua.unlocked[i].classList.remove("sua-unlock");
		sua.unlocked = [];
	}
	function suaLockWrappers(video) {
		var node = video && video.parentElement;
		for (var depth = 0; node && depth < 3; depth++) {
			if (node === document.body || node === document.documentElement) break;
			// v6.40.8 fix24f：小窗宿主不加 sua-unlock——它的尺寸归 suaApplyMini 管；
			// .sua-unlock 的 height:auto!important 会顶掉宿主的 180px，全屏退出后宿主撑满屏。
			if (node.id !== "sua-mini-host") { node.classList.add("sua-unlock"); sua.unlocked.push(node); }
			node = node.parentElement;
		}
	}
	function suaSizeCss() {
		var state = sua.state;
		var vw = window.innerWidth || document.documentElement.clientWidth || 0;
		var vh = window.innerHeight || document.documentElement.clientHeight || 0;
		var portrait = vh >= vw;
		if (state.size === "fit") return null;
		if (state.size === "auto") {
			var autoW = portrait ? Math.round(vw * 0.995) : Math.min(Math.max(320, Math.round(vw) - 32), 1440);
			return {
				position: "static",
				width: Math.max(220, autoW) + "px",
				height: "auto",
				maxWidth: "100vw",
				maxHeight: Math.round(vh * (portrait ? 0.62 : 0.86)) + "px",
				minWidth: "0",
				minHeight: "0",
				margin: "0 auto",
				display: "block",
				objectFit: "contain",
				background: "#000",
				zIndex: ""
			};
		}
		if (state.size === "fill") return {
			position: "fixed",
			left: "0",
			top: "0",
			right: "0",
			bottom: "0",
			width: "100vw",
			height: "100vh",
			maxWidth: "none",
			maxHeight: "none",
			minWidth: "0",
			minHeight: "0",
			margin: "0",
			objectFit: "contain",
			background: "#000",
			zIndex: "2147481000"
		};
		var width;
		if (state.size === "custom") width = Math.round(vw * (Math.min(150, Math.max(50, state.customW)) / 100));
		else if (state.size === "comfort") width = Math.round(vw * (portrait ? 0.96 : 0.78));
		else width = Math.round(vw * (portrait ? 0.99 : 0.94));
		var maxHeight = Math.round(vh * (portrait ? 0.56 : 0.92));
		return {
			position: "static",
			width: Math.max(220, width) + "px",
			height: "auto",
			maxWidth: "100vw",
			maxHeight: maxHeight + "px",
			minWidth: "0",
			minHeight: "0",
			margin: "0 auto",
			display: "block",
			objectFit: "contain",
			background: "#000",
			zIndex: ""
		};
	}
	function suaApplyAspect(video) {
		if (!video || sua.paused) return;
		try {
			if (suaProfile().ownPlayer && !sua.owned) return;
		} catch (error) {}
		var aspect = sua.state.aspect || "off";
		if (aspect === "off") return;
		if (sua.state.size === "fill") return;
		suaSetImportant(video, "aspect-ratio", String(aspect).replace(":", " / "));
		suaSetImportant(video, "object-fit", "cover");
		suaSetImportant(video, "height", "auto");
		suaSetImportant(video, "max-height", "none");
	}
	function suaApplySize() {
		var video = sua.video;
		if (!video || sua.paused) return;
		if (sua.hubPlaying) return; // v6.19.0：聚合页内置播放器尺寸由面板 CSS 管，不套通用尺寸
		try {
			if (suaProfile().ownPlayer && !sua.owned) return;
		} catch (error) {}
		suaUnlockWrappers();
		["width", "height", "max-width", "max-height", "min-width", "min-height", "margin", "object-fit", "background", "position", "left", "top", "right", "bottom", "display", "z-index"].forEach(function (prop) {
			suaSetImportant(video, prop, "");
		});
		var css = suaSizeCss();
		if (css) {
			Object.keys(css).forEach(function (key) {
				if (css[key]) suaSetImportant(video, key, css[key]);
			});
			suaLockWrappers(video);
		}
		suaApplyAspect(video);
	}
	function suaApplyFilter() {
		var video = sua.video;
		if (!video || sua.paused) return;
		try {
			if (suaProfile().ownPlayer && !sua.owned) return;
		} catch (error) {}
		var state = sua.state;
		var parts = [];
		if (state.brightness !== 100) parts.push("brightness(" + state.brightness + "%)");
		if (state.contrast !== 100) parts.push("contrast(" + state.contrast + "%)");
		if (state.saturate !== 100) parts.push("saturate(" + state.saturate + "%)");
		if (state.hue) parts.push("hue-rotate(" + state.hue + "deg)");
		if (state.invert) parts.push("invert(1)");
		suaSetImportant(video, "filter", parts.length ? parts.join(" ") : "");
		var transform = [];
		if (state.rotate) transform.push("rotate(" + state.rotate + "deg)");
		if (state.mirror) transform.push("scaleX(-1)");
		if (state.zoom !== 100) transform.push("scale(" + state.zoom / 100 + ")");
		suaSetImportant(video, "transform", transform.length ? transform.join(" ") : "");
	}
	function suaApplyPlayback() {
		var video = sua.video;
		if (!video || sua.paused) return;
		try {
			if (suaProfile().ownPlayer && !sua.owned) return;
		} catch (error) {}
		var state = sua.state;
		sua.applyingVolume = true;
		try {
			if (state.rate && Math.abs((video.playbackRate || 1) - state.rate) > 0.01) video.playbackRate = state.rate;
			video.loop = Boolean(state.loop);
			if (typeof state.volume === "number" && Math.abs((video.volume || 0) - state.volume) > 0.02) video.volume = Math.max(0, Math.min(1, state.volume));
			video.muted = Boolean(state.muted);
		} catch (error) {}
		sua.applyingVolume = false;
	}
	// v6.25.0：网站底色（MissAV 也能用；不走 suaApplyTheme，那个在 MissAV 上会直接 return）
	function suaApplySiteBg() {
		var root = document.documentElement;
		var color = "";
		try { color = String((sua.state && sua.state.siteBg) || ""); } catch (error) {}
		var on = false;
		try { on = suaEnabled() && !sua.paused && !!color; } catch (error) {}
		if (!on) {
			try { root.removeAttribute("data-sua-sitebg"); } catch (error) {}
			try { root.style.removeProperty("--sua-site-bg"); } catch (error) {}
			return;
		}
		try { root.style.setProperty("--sua-site-bg", color); } catch (error) {}
		try { root.setAttribute("data-sua-sitebg", "1"); } catch (error) {}
	}
	function suaApplyAll() {
		try { suaApplyMiniZ(); } catch (error) {}
		try { suaApplyLook(); } catch (error) {}
		suaApplySiteBg();
		suaApplySize();
		suaApplyFilter();
		suaApplyPlayback();
		suaApplySubtitleStyle();
		suaPositionOverlay();
		suaApplyMini();
		try { suaApplyPanelFull(); } catch (error) {}
	}
	// v6.15.0 悬浮小窗：视频脱离页面、固定在右下角；用 suaSetImportant 写（size 也是 important，普通 style 会被盖掉）。
	// MissAV 的站内控制条不会跟进小窗，用视频旁的快捷条控制；全屏时不开小窗。
