								var ar2 = (sua.docPinch.startH && sua.docPinch.startW) ? (sua.docPinch.startW / sua.docPinch.startH) : (16 / 9);
								var nh2 = Math.round(Math.max(120, Math.min(vh - 8, nw / ar2)));
