	//（不用被 hook 过的 JSON.parse），避免重复走 hook。
	var SUA_LTX_HOOKED = false;
	function suaLtxInstallHooks() {
		if (SUA_LTX_HOOKED) return;
		try {
			var host = String(location.hostname || "").toLowerCase();
			if (host !== "ltxlib.dpdns.org" && host.slice(-17) !== ".ltxlib.dpdns.org") return;
		} catch (e) { return; }
		var uw = null;
		try { uw = (typeof unsafeWindow !== "undefined" && unsafeWindow) || window; } catch (e) { uw = window; }
		if (!uw || !uw.JSON) return;
		try {
			var origParse = uw.JSON.parse;
			uw.JSON.parse = function (text) {
				var out = origParse.apply(this, arguments);
				try { if (typeof text === "string" && text.length > 1500) suaLtxCapturePush(out, "JSON.parse"); } catch (e) {}
				return out;
			};
			if (uw.TextDecoder && uw.TextDecoder.prototype && uw.TextDecoder.prototype.decode) {
				var origDecode = uw.TextDecoder.prototype.decode;
				uw.TextDecoder.prototype.decode = function () {
					var s = origDecode.apply(this, arguments);
					try {
						if (typeof s === "string" && s.length > 1500 && /(ed2k:\/\/|magnet:|"items"|"list"|"code"|"title"|[\u4e00-\u9fff])/.test(s)) {
							var o = origParse(s);
							suaLtxCapturePush(o, "TextDecoder");
						}
					} catch (e) {}
					return s;
				};
			}
			SUA_LTX_HOOKED = true;
		} catch (e) {}
	}
	// v6.40.25 fix41 §2.3：在实时捕获里搜。番号按归一化番号精确匹配；片名/演员
	// 按子串匹配。返回扫描要的 {hit, note, url, videos}（videos 是
	// suaResPickList 同格式：{title, url, cover, siteId, siteName, score}）。
	function suaLtxLiveSearch(query) {
		var live = suaLtxLiveLoad();
		if (!live.length) return { hit: false, note: "先打开 LTX 站浏览一次，抓到数据后这里才有结果", url: "https://ltxlib.dpdns.org/", videos: [] };
		var q = String(query || "").trim();
		var qn = "";
		try { qn = normalizeVideoCode(q) || ""; } catch (e) {}
		// normalizeVideoCode 对非番号也原样返回，不能用 !!qn 判番号；用 suaIsCode。
		var isCode = false;
		try { isCode = !!(qn && suaIsCode(qn)); } catch (e) {}
		var out = [];
		for (var i = 0; i < live.length && out.length < 12; i++) {
			var r = live[i];
			if (!r) continue;
			var ok = false;
			if (isCode) ok = String(r[SUA_LTX_IDX.code] || "").toUpperCase() === qn;
			else {
				var hay = String(r[SUA_LTX_IDX.title] || "") + " " + String((r[SUA_LTX_IDX.actors] || []).join(" ")) + " " + String(r[SUA_LTX_IDX.maker] || "");
				ok = hay.toLowerCase().indexOf(q.toLowerCase()) >= 0;
			}
			if (!ok) continue;
			out.push({ title: String(r[SUA_LTX_IDX.title] || r[SUA_LTX_IDX.code] || ""), url: "https://ltxlib.dpdns.org/", cover: String(r[SUA_LTX_IDX.cover] || ""), siteId: "ltxlib", siteName: "LTX 4K（站内）", score: 10 });
		}
		return { hit: out.length > 0, note: out.length ? ("站内实时捕获 " + out.length + " 条") : "站内捕获里没这部", url: "https://ltxlib.dpdns.org/", videos: out };
	}
	// 字节数 → “7.6 GB” / “850 MB” / “12 KB”。
	function suaLtxFmtSize(bytes) {
		var n = Number(bytes) || 0;
		if (n <= 0) return "";
		if (n >= 1073741824) return (Math.round(n / 1073741824 * 10) / 10) + " GB";
		if (n >= 1048576) return (Math.round(n / 1048576 * 10) / 10) + " MB";
		if (n >= 1024) return (Math.round(n / 1024 * 10) / 10) + " KB";
		return n + " B";
	}

	// v6.40.26 fix42：JavRanking 榜单——走自家网页版 Worker（app.keylee.eu.cc）的
	// /api/ranking、/api/chong 代理，不拉 19MB 索引。线上已验：单条/batch/top/
	// random/check/create/sync 全通。注意 Worker 的同步路由是 POST /api/chong/sync
	//（code 在 body），不是上游的 /api/chong-code/{code}/sync。
	var SUA_RANK_API = "https://app.keylee.eu.cc/api";
	var SUA_RANK_CACHE = {};
	var SUA_RANK_BATCH_PENDING = {};
	var SUA_CHONG_MARKS_KEY = "suaChongMarks_v1";
	var SUA_CHONG_QUEUE_KEY = "suaChongQueue_v1";
	var SUA_CHONG_CODE_KEY = "suaChongCode_v1";
	var SUA_CHONG_SYNC_KEY = "suaChongSync_v1";
	var SUA_CHONG_CODE_RE = /^[A-Za-z0-9]{6,16}$/;
	// POST JSON：GM 直连优先，fetch 兜底；不走代理链（同步只认自家 Worker，
	// keylee-cors 不放行 javranking.cc，代理只会 403）。失败就 reject，调用方
	// 把标记留本地、提示“同步暂不可用”。
	function suaGmPostJson(url, obj, timeout) {
		return new Promise(function (resolve, reject) {
			var body = "";
			try { body = JSON.stringify(obj || {}); } catch (e) {}
			var headers = { "Content-Type": "application/json", Accept: "application/json" };
			var fetchPost = function () {
				if (typeof fetch !== "function") return reject(new Error("无可用请求方式"));
				fetch(url, { method: "POST", body: body, headers: headers }).then(function (r) {
					if (!r.ok) throw new Error("HTTP " + r.status);
					return r.text();
				}).then(resolve, reject);
			};
			if (typeof GM_xmlhttpRequest === "function") {
				GM_xmlhttpRequest({
					method: "POST", url: url, data: body, timeout: timeout || 12000, headers: headers,
					onload: function (res) {
						if (res && res.status >= 200 && res.status < 400) resolve(String(res.responseText || ""));
						else reject(new Error("HTTP " + (res ? res.status : 0)));
					},
					onerror: function () { fetchPost(); },
					ontimeout: function () { reject(new Error("请求超时")); }
				});
				return;
			}
			fetchPost();
		});
	}
	// 单条榜单：GET /api/ranking?code=。返回原样 JSON（ok/ranked/inIndex/rank/
	// score/appearances/detailUrl/previewUrl…）；失败返回 {ok:false}，调用方显示
	// “榜单暂不可用”，绝不编造。
	function suaRankGet(code) {
		var c = "";
		try { c = normalizeVideoCode(code) || ""; } catch (e) {}
		if (!c) return Promise.resolve({ ok: false });
		try { if (!suaIsCode(c)) return Promise.resolve({ ok: false }); } catch (e) {}
		if (SUA_RANK_CACHE[c]) return Promise.resolve(SUA_RANK_CACHE[c]);
		return suaGmGet(SUA_RANK_API + "/ranking?code=" + encodeURIComponent(c), 12000).then(function (r) {
			var d = null;
			try { d = JSON.parse(r.text); } catch (e) {}
			if (!d || typeof d !== "object") d = { ok: false };
			SUA_RANK_CACHE[c] = d;
			return d;
		}).catch(function () { return { ok: false }; });
	}
	// 批量取排名角标：GET /api/ranking/batch?codes=A,B（上限 20）。只拉缓存里没有的，
	// 结果逐条进缓存；失败返回已缓存的部分（卡片不显示角标，不编造）。
	function suaRankBatch(codes) {
		var todo = [];
		var seen = {};
		var out = {};
		(codes || []).forEach(function (raw) {
			var c = "";
			try { c = normalizeVideoCode(raw) || ""; } catch (e) {}
			if (!c || seen[c]) return;
			seen[c] = 1;
			if (SUA_RANK_CACHE[c]) { out[c] = SUA_RANK_CACHE[c]; return; }
			if (SUA_RANK_BATCH_PENDING[c]) return;
			todo.push(c);
		});
		if (!todo.length) return Promise.resolve(out);
		todo.forEach(function (c) { SUA_RANK_BATCH_PENDING[c] = 1; });
		var qs = todo.slice(0, 20).join(",");
		return suaGmGet(SUA_RANK_API + "/ranking/batch?codes=" + encodeURIComponent(qs), 12000).then(function (r) {
			var d = null;
			try { d = JSON.parse(r.text); } catch (e) {}
			var res = (d && d.results) || {};
			Object.keys(res).forEach(function (k) { SUA_RANK_CACHE[k] = res[k]; });
			// v6.40.26 fix42h：服务端没回的番号也记一笔 {ranked:false}（Worker 正常会给
			// 每个请求的番号都回一条，但万一漏了也不让填充死循环重拉——探针里桩只回 4 条、
			// LTX Tab 有 60 张卡时就这么卡死了）。
			todo.forEach(function (c) { if (!SUA_RANK_CACHE[c]) SUA_RANK_CACHE[c] = { ranked: false, rank: null, score: null, videoId: null, hasPreviewVideo: false }; });
			todo.forEach(function (c) { delete SUA_RANK_BATCH_PENDING[c]; });
			todo.forEach(function (c) { if (SUA_RANK_CACHE[c]) out[c] = SUA_RANK_CACHE[c]; });
			return out;
		}).catch(function () {
			todo.forEach(function (c) { delete SUA_RANK_BATCH_PENDING[c]; });
			return out;
		});
	}
	// 榜单列表：GET /api/ranking/top?mode=top|random&offset=&limit=。返回原样 JSON
	//（ok/mode/total/totalIndexed/offset/limit/items[]）；失败返回 {ok:false}。
	function suaRankTop(mode, offset, limit) {
		var m = mode === "random" ? "random" : "top";
		var off = Math.max(0, Number(offset) || 0);
		var lim = Math.max(1, Math.min(48, Number(limit) || 24));
		return suaGmGet(SUA_RANK_API + "/ranking/top?mode=" + m + "&offset=" + off + "&limit=" + lim, 15000).then(function (r) {
			var d = null;
			try { d = JSON.parse(r.text); } catch (e) {}
			if (!d || typeof d !== "object" || !d.ok || !Array.isArray(d.items)) return { ok: false, mode: m, offset: off, limit: lim, items: [] };
			return d;
		}).catch(function () { return { ok: false, mode: m, offset: off, limit: lim, items: [] }; });
	}
	// 从卡片标题里抠番号（聚合卡片只有标题，没有 code 字段）。FC2 先认，别的只认
	// 标准番号形；抠不到返回 ""（不显示角标，不编造）。
	function suaRankCodeFromTitle(title) {
		var t = String(title || "");
		var m = t.match(/FC2(?:-PPV)?-\d{6,7}/i);
		if (m) return m[0].toUpperCase();
		m = t.match(/[A-Za-z]{2,6}-\d{2,5}/);
		if (!m) return "";
		var c = m[0].toUpperCase();
		try { return suaIsCode(c) ? c : ""; } catch (e) { return c; }
	}
	// 纯函数：详情卡的 JavRanking 榜单区（照网页版 v5 同款文案/三态）。三种状态：
	//  - !ok：榜单暂不可用（索引拉不到，不阻塞详情其他部分）
	//  - ranked=false + inIndex：暂无总排名（在索引里但无总榜名次），上榜记录照常列，
	//    负分不展示（score<=0 时不显示分数）
	//  - ranked=false（不在索引）：暂未上榜单（只收录上过榜单的影片，未上榜 ≠ 不存在）
	//  - ranked：金色总榜角标（第 1 名醒目）+ ★总分（>0 才显示）+ 上榜记录
	//    （>3 条收起 + 展开全部）+ 预告/详情链接。
	function suaRankSectionHtml(d) {
		var head = '<div class="row2" style="font-weight:700">🏆 JavRanking 榜单</div>';
		if (!d || !d.ok) return '<div class="rank-sec">' + head + '<p class="hint">榜单暂不可用（稍后再试；不影响搜索/详情）</p></div>';
		var appRow = function (a) {
			var slug = String((a && a.slug) || "");
			var name = String((a && a.name) || "");
			var year = a && a.year ? " " + a.year : "";
			var pos = a && a.position != null ? a.position : "";
			return '<a class="rank-app" href="https://javranking.cc/zh-hans/rankings/' + suaEsc(slug) + '/" target="_blank" rel="noopener"><span>' + suaEsc(name + year) + '</span><b>第 ' + suaEsc(String(pos)) + ' 名</b></a>';
		};
		var appsHtml = function (apps) {
			var list = Array.isArray(apps) ? apps : [];
			if (!list.length) return "";
			var shown = list.slice(0, 3);
			var rest = list.slice(3);
			var h = '<div class="rank-apps">' + shown.map(appRow).join("") + (rest.length ? '<div class="rank-rest" style="display:none">' + rest.map(appRow).join("") + '</div>' : '') + '</div>';
			if (rest.length) h += '<div class="row2"><button class="btn small ghost" data-act="rank-more">展开全部（共 ' + list.length + ' 条上榜记录）</button></div>';
			return h;
		};
		var linksHtml = function () {
			if (!d.detailUrl && !(d.hasPreviewVideo && d.previewUrl)) return "";
			var h = '<div class="row2">';
			if (d.detailUrl) h += '<a class="btn small ghost" href="' + suaEsc(d.detailUrl) + '" target="_blank" rel="noopener">在 JavRanking 查看详情 ↗</a> ';
			if (d.hasPreviewVideo && d.previewUrl) h += '<a class="btn small" href="' + suaEsc(d.previewUrl) + '" target="_blank" rel="noopener">去 JavRanking 看预告 ▶</a>';
			return h + '</div>';
		};
		if (!d.ranked && d.inIndex) {
			var apps0 = d.appearances || [];
			return '<div class="rank-sec">' + head
				+ '<p class="hint">暂无总排名<span style="color:var(--mute)"> · 在 JavRanking 索引里，但暂无总榜名次</span></p>'
				+ (apps0.length ? appsHtml(apps0) : '<p class="hint">暂无单榜上榜记录</p>')
				+ linksHtml() + '</div>';
		}
		if (!d.ranked) return '<div class="rank-sec">' + head + '<p class="hint">暂未上榜单<span style="color:var(--mute)"> · JavRanking 只收录上过榜单的影片，未上榜不代表这部不存在</span></p></div>';
		var scoreHtml = (typeof d.score === "number" && d.score > 0) ? '<span class="rank-score">★ ' + d.score + ' 分</span>' : '';
		var apps = d.appearances || [];
		return '<div class="rank-sec">' + head
			+ '<div class="row2"><span class="rank-big' + (d.rank === 1 ? ' first' : '') + '">总榜第 ' + d.rank + ' 名</span> ' + scoreHtml + '</div>'
			+ (apps.length ? appsHtml(apps) : '<p class="hint">有总排名，但暂无单榜上榜记录</p>')
			+ linksHtml() + '</div>';
	}
	// 详情卡榜单区填充：按番号查单条，填进 [data-rank-box]。只认当前盒子的
	// data-code（详情卡重渲染后旧请求的结果直接丢弃，不串位）。
	function suaRankFillDetail(code) {
		var c = "";
		try { c = normalizeVideoCode(code) || ""; } catch (e) {}
		if (!c) return;
		suaRankGet(c).then(function (d) {
			try {
				var box = sua.ui && sua.ui.root ? sua.ui.root.querySelector('[data-rank-box][data-code="' + c + '"]') : null;
				if (!box) return;
				box.innerHTML = suaRankSectionHtml(d);
			} catch (e) {}
		});
	}
	// 聚合卡片排名角标填充：扫一遍网格里 [data-rank-badge]，缓存里有的直接填，
	// 没有的批量拉一次（上限 20），回来再填一遍。没排名的不显示角标，不编造。
	function suaRankFillBadges() {
		var page = null;
		try { page = suaHubPageEl(); } catch (e) {}
		if (!page) return;
		var grid = page.querySelector("[data-hp-grid]");
		if (!grid) return;
		var spans = grid.querySelectorAll("[data-rank-badge]");
		var missing = [];
		var seen = {};
		for (var i = 0; i < spans.length; i++) {
			var sp = spans[i];
			var code = sp.getAttribute("data-code") || "";
			if (!code) { sp.style.display = "none"; continue; }
			var hit = SUA_RANK_CACHE[code];
			if (hit && hit.ranked && hit.rank != null) {
				sp.textContent = "#" + hit.rank;
				sp.style.display = "";
				if (hit.rank <= 10) sp.classList.add("top10");
				sp.setAttribute("data-done", "1");
				continue;
			}
			if (hit) { sp.style.display = "none"; sp.setAttribute("data-done", "1"); continue; }
			if (sp.getAttribute("data-done")) continue;
			if (!seen[code]) { seen[code] = 1; missing.push(code); }
		}
		if (!missing.length) return;
		// v6.40.26 fix42i：同一时刻只允许一批在途。否则第二次填充会发现同一批
		// 番号“缺失”（缓存还没回、batch 在途），suaRankBatch 因全 pending 而立即
		// resolve，.then 又调填充——微任务先于定时器，GM 回包永远等不到，死循环
		// 拖死渲染器（LTX Tab 点一下就崩页就是这么来的）。
		if (sua._rankFilling) return;
		sua._rankFilling = true;
		suaRankBatch(missing).then(function () {
			sua._rankFilling = false;
			try { suaRankFillBadges(); } catch (e) {}
		}, function () {
			sua._rankFilling = false;
		});
	}
	// ---- 冲码（已冲/待冲）本地存储 + 同步。照网页版 v5 同款语义：标记先写本地
	//（离线可用），变化进队列，1.5 秒防抖后 POST /api/chong/sync；服务端按
	// markedAt 做 Last-Write-Wins，status=none 的墓碑删掉该条。
	function suaChongMarksRead() {
		try { var v = suaRead(SUA_CHONG_MARKS_KEY); return v && typeof v === "object" ? v : {}; } catch (e) { return {}; }
	}
	function suaChongMarksSave(m) { try { suaWrite(SUA_CHONG_MARKS_KEY, m || {}); } catch (e) {} }
	function suaChongQueueRead() {
		try { var v = suaRead(SUA_CHONG_QUEUE_KEY); return Array.isArray(v) ? v : []; } catch (e) { return []; }
	}
	function suaChongQueueSave(q) { try { suaWrite(SUA_CHONG_QUEUE_KEY, Array.isArray(q) ? q : []); } catch (e) {} }
	function suaChongCodeGet() { try { return String(suaRead(SUA_CHONG_CODE_KEY) || "").trim(); } catch (e) { return ""; } }
	function suaChongCodeSet(code) { try { suaWrite(SUA_CHONG_CODE_KEY, JSON.stringify(String(code || "").trim())); } catch (e) {} } // v6.40.26 fix42g：suaRead 会对存的字符串做 JSON.parse，裸字符串读回来是 fallback——码必须 JSON 编码存，否则重载页面后绑定就丢了（S56 测出来的真 bug）。
	function suaChongSyncGet() { try { var v = suaRead(SUA_CHONG_SYNC_KEY); return v && typeof v === "object" ? v : {}; } catch (e) { return {}; } }
	function suaChongSyncSave(s) { try { suaWrite(SUA_CHONG_SYNC_KEY, s || {}); } catch (e) {} }
	function suaChongStatus(code) {
		var c = "";
		try { c = normalizeVideoCode(code) || ""; } catch (e) {}
		if (!c) return "";
		var m = suaChongMarksRead();
		var it = m[c];
		return it && (it.status === "done" || it.status === "wish") ? it.status : "";
	}
	function suaChongMarkLabel(status) {
		return status === "done" ? "✓ 已冲" : status === "wish" ? "☆ 待冲" : "＋ 标记";
	}
	// 一键切换：无 → 已冲 → 待冲 → 无。先写本地（离线可用），再进同步队列。
	function suaChongCycle(code) {
		var cur = suaChongStatus(code);
		var next = cur === "" ? "done" : cur === "done" ? "wish" : "none";
		suaChongSet(code, next);
		return next;
	}
	function suaChongSet(code, status) {
		var c = "";
		try { c = normalizeVideoCode(code) || ""; } catch (e) {}
		if (!c) return "";
		var st = status === "done" || status === "wish" ? status : "none";
		var now = Math.floor(Date.now() / 1000);
		var marks = suaChongMarksRead();
		if (st === "none") delete marks[c];
		else marks[c] = { status: st, markedAt: now };
		suaChongMarksSave(marks);
		var q = suaChongQueueRead();
		q = q.filter(function (it) { return it && it.videoCode !== c; });
		q.push({ videoCode: c, status: st, markedAt: now });
		suaChongQueueSave(q.slice(-200));
		try { suaChongScheduleSync(); } catch (e) {}
		try { suaChongRefreshMarkUis(c); } catch (e) {}
		return st;
	}
	function suaChongScheduleSync() {
		try { if (sua._chongTimer) clearTimeout(sua._chongTimer); } catch (e) {}
		sua._chongTimer = setTimeout(function () { sua._chongTimer = null; try { suaChongSyncNow(false, false); } catch (e) {} }, 1500);
	}
	// 同步：POST /api/chong/sync {code, since, changes}。没绑码就只留本地；
	// 失败也只留本地，队列不动，下次再试。成功后按 markedAt 做 LWW 合并。
	function suaChongSyncNow(manual, fullUpload) {
		var code = suaChongCodeGet();
		if (!code) return Promise.resolve({ ok: false, reason: "no_code" });
		if (sua._chongSyncing) return Promise.resolve({ ok: false, reason: "busy" });
		sua._chongSyncing = true;
		var syncState = suaChongSyncGet();
		var since = Number(syncState.since) || 0;
		var changes = suaChongQueueRead();
		if (fullUpload) {
			var marks = suaChongMarksRead();
			var byCode = {};
			Object.keys(marks).forEach(function (k) {
				var it = marks[k];
				if (it && (it.status === "done" || it.status === "wish")) byCode[k] = { videoCode: k, status: it.status, markedAt: it.markedAt || 0 };
			});
			changes.forEach(function (it) { if (it && it.videoCode) byCode[it.videoCode] = { videoCode: it.videoCode, status: it.status, markedAt: it.markedAt || 0 }; });
			changes = Object.keys(byCode).map(function (k) { return byCode[k]; });
		}
		changes = changes.filter(function (it) { return it && it.videoCode && (it.status === "done" || it.status === "wish" || it.status === "none") && it.markedAt != null; }).slice(0, 200);
		return suaGmPostJson(SUA_RANK_API + "/chong/sync", { code: code, since: since, changes: changes }, 15000).then(function (text) {
			var d = null;
			try { d = JSON.parse(text); } catch (e) {}
			if (!d || !d.ok || !Array.isArray(d.items)) throw new Error((d && (d.error || d.reason)) || "同步失败");
			suaChongMergeItems(d.items || []);
			suaChongQueueSave([]);
			suaChongSyncSave({ since: d.syncedAt || Math.floor(Date.now() / 1000), at: Date.now(), ok: true });
			try { suaChongRenderBox(); } catch (e) {}
			try { suaChongRenderList(); } catch (e) {}
			if (manual) { try { suaToast("冲码同步完成"); } catch (e) {} }
			return { ok: true };
		}).catch(function (err) {
			suaChongSyncSave({ since: since, at: Date.now(), ok: false, reason: String((err && err.message) || err) });
			try { suaChongRenderBox(); } catch (e) {}
			if (manual) { try { suaToast("同步暂不可用（标记已保存在本机）"); } catch (e) {} }
			return { ok: false, reason: String((err && err.message) || err) };
		}).then(function (r) { sua._chongSyncing = false; return r; });
	}
	// LWW 合并服务端标记（照网页版同款语义）：服务端 markedAt 更大的覆盖本地；
	// 本地有更新的待同步变化时保留本地；服务端 status=none 表示对端已取消，删本地标记。
	function suaChongMergeItems(serverItems) {
		var all = suaChongMarksRead();
		var queue = suaChongQueueRead();
		var queued = {};
		queue.forEach(function (c) { if (c && c.videoCode) queued[c.videoCode] = c; });
		var changed = {};
		(serverItems || []).forEach(function (it) {
			var c = "";
			try { c = normalizeVideoCode(it.videoCode || "") || ""; } catch (e) {}
			if (!c) return;
			var srvAt = typeof it.markedAt === "number" ? it.markedAt : Math.floor(new Date(it.markedAt).getTime() / 1000) || 0;
			var local = all[c];
			var localAt = local ? (local.markedAt || 0) : 0;
			var pending = queued[c];
			if (pending && pending.markedAt >= srvAt) return;
			if (srvAt < localAt) return;
			if (it.status === "none") delete all[c];
			else if (it.status === "done" || it.status === "wish") all[c] = { status: it.status, markedAt: srvAt };
			changed[c] = 1;
		});
		suaChongMarksSave(all);
		Object.keys(changed).forEach(function (c) { try { suaChongRefreshMarkUis(c); } catch (e) {} });
		return all;
	}
	// 刷新一处番号在所有可见位置的标记按钮（详情卡两个切换钮、聚合卡片循环钮、
	// 收藏 Tab 的标记列表）。详情卡重渲染时会自己按最新状态画，这里只改已在 DOM 里的。
	function suaChongRefreshMarkUis(code) {
		var c = "";
		try { c = normalizeVideoCode(code) || ""; } catch (e) {}
		if (!c || !sua.ui || !sua.ui.root) return;
		var st = suaChongStatus(c);
		var root = sua.ui.root;
		try {
			var doneBtns = root.querySelectorAll('[data-act="chong-done"][data-code="' + c + '"]');
			for (var i = 0; i < doneBtns.length; i++) doneBtns[i].classList.toggle("is-on", st === "done");
			var wishBtns = root.querySelectorAll('[data-act="chong-wish"][data-code="' + c + '"]');
			for (var j = 0; j < wishBtns.length; j++) wishBtns[j].classList.toggle("is-on", st === "wish");
			var cyc = root.querySelectorAll('[data-hp="chong-cycle"][data-code="' + c + '"]');
			for (var k = 0; k < cyc.length; k++) {
				cyc[k].textContent = st === "done" ? "✓" : st === "wish" ? "☆" : "＋";
				cyc[k].classList.toggle("on-done", st === "done");
				cyc[k].classList.toggle("on-wish", st === "wish");
				cyc[k].setAttribute("title", st === "done" ? "已冲（点一下改待冲）" : st === "wish" ? "待冲（点一下取消）" : "标记：点一下设为已冲");
			}
		} catch (e) {}
		try { suaChongRenderList(); } catch (e) {}
		try { suaChongRenderBox(); } catch (e) {}
	}

	// 收藏 Tab 的冲码卡片：未绑定 → 输入 + 绑定 / 生成；已绑定 → 显示冲码 +
	// 数量 + 同步状态 + 立即同步 / 解绑。冲码是唯一凭证，知道码的人能看到标记。
	function suaChongRenderBox() {
		var box = null;
		try { box = sua.ui && sua.ui.root ? sua.ui.root.querySelector("[data-chong-box]") : null; } catch (e) {}
		if (!box) return;
		var code = suaChongCodeGet();
		var marks = suaChongMarksRead();
		var done = 0, wish = 0;
		Object.keys(marks).forEach(function (k) { if (marks[k].status === "done") done++; else if (marks[k].status === "wish") wish++; });
		var queue = suaChongQueueRead().length;
		var st = suaChongSyncGet();
		// 签名不变就不重绘——否则每次 suaSync 都会清空用户正在输的冲码输入框。
		var sig = [code, done, wish, queue, st.ok ? "1" : "0", st.at ? Math.floor(st.at / 60000) : ""].join("|");
		if (sua._chongBoxSig === sig) return;
		var typed = "";
		try { var _inp0 = box.querySelector("[data-chong-input]"); if (_inp0) typed = _inp0.value || ""; } catch (e) {}
		sua._chongBoxSig = sig;
		var syncWhen = "";
		if (st.at) {
			var mins = Math.max(0, Math.floor((Date.now() - st.at) / 60000));
			if (mins < 1) syncWhen = "刚刚";
			else if (mins < 60) syncWhen = mins + " 分钟前";
			else { try { syncWhen = suaFmtDate(st.at) || ""; } catch (e2) {} }
		}
		var syncLine = "";
		if (code) {
			if (st && st.at) syncLine = st.ok ? ("上次同步 " + (syncWhen || "刚刚") + (queue ? " · 待同步 " + queue + " 条" : " · 已同步")) : ("同步暂不可用" + (queue ? " · 待同步 " + queue + " 条（已保存在本机）" : "（标记已保存在本机）"));
			else if (queue) syncLine = "待同步 " + queue + " 条";
			else syncLine = "本地标记只存在本机，绑冲码后多端同步";
		}
		if (!code) {
			box.innerHTML = '<div class="row"><input class="inp" data-chong-input placeholder="输入已有冲码（6–16 位字母数字）" style="flex:1" autocomplete="off"><button class="btn small primary" data-act="chong-bind">绑定</button><button class="btn small ghost" data-act="chong-create">生成新冲码</button></div>'
				+ '<p class="hint">生成会得到一个 8 位冲码，记下来，换设备时输同一个码就能同步。冲码是唯一凭证，知道码的人能看到你的标记，别公开分享。</p>'
				+ '<p class="hint">已冲 ' + done + ' 部 · 待冲 ' + wish + ' 部（只存本机）</p>';
		} else {
			box.innerHTML = '<div class="row"><span style="font-weight:700">冲码：' + suaEsc(code) + '</span><button class="btn small ghost" data-act="chong-copy">复制</button><button class="btn small" data-act="chong-sync">立即同步</button><button class="btn small ghost" data-act="chong-unbind">解绑</button></div>'
				+ '<p class="hint">已冲 ' + done + ' 部 · 待冲 ' + wish + ' 部' + (syncLine ? ' · ' + suaEsc(syncLine) : '') + '</p>';
		}
		if (!code && typed) {
			try { var _inp2 = box.querySelector("[data-chong-input]"); if (_inp2) _inp2.value = typed; } catch (e3) {}
		}
	}
	// 收藏 Tab 的标记列表：已冲/待冲的番号，点一下进聚合页按番号搜，✕ 取消标记。
	function suaChongRenderList() {
		var box = null;
		try { box = sua.ui && sua.ui.root ? sua.ui.root.querySelector("[data-chong-list]") : null; } catch (e) {}
		if (!box) return;
		var marks = suaChongMarksRead();
		var codes = Object.keys(marks).sort(function (a, b) { return (marks[b].markedAt || 0) - (marks[a].markedAt || 0); });
		if (!codes.length) { box.innerHTML = '<p class="empty">还没有标记。在详情卡或聚合卡片上点 ✓ / ☆ 就能记下来。</p>'; return; }
		box.innerHTML = codes.map(function (c) {
			var it = marks[c] || {};
			var label = it.status === "done" ? "✓ 已冲" : "☆ 待冲";
			return '<div class="item"><b>' + suaEsc(c) + '</b><div class="meta"><span>' + label + '</span></div>'
				+ '<div class="ops"><button class="btn small" data-act="chong-open" data-code="' + suaEsc(c) + '">看详情</button>'
				+ '<button class="btn small ghost" data-act="chong-del" data-code="' + suaEsc(c) + '">取消标记</button></div></div>';
		}).join("");
	}
	// 绑定流程：设码 → since 归零（下次同步全量拉）→ 刷新卡片 → 全量同步（本地标记上传）。
	function suaChongDoBind(code) {
		suaChongCodeSet(code);
		try { suaChongSyncSave({ since: 0, at: 0, ok: true }); } catch (e) {}
		try { suaChongRenderBox(); } catch (e2) {}
		try { suaToast("冲码已绑定：" + code); } catch (e3) {}
		try { suaChongSyncNow(false, true); } catch (e4) {}
	}
	// 生成/认领：code 为空 → 服务端自动生成 8 位；有码 → 认领该码。
	function suaChongDoCreate(code) {
		var body = code ? { code: code } : {};
		return suaGmPostJson(SUA_RANK_API + "/chong/create", body, 12000).then(function (text) {
			var d = null;
			try { d = JSON.parse(text); } catch (e) {}
			if (!d || !d.ok || !d.code) throw new Error((d && (d.error || d.reason)) || "生成失败");
			suaChongDoBind(d.code);
			return d;
		});
	}

// fix31: EUC-JP percent-encoder, ported from the public Escape Codec Library
// (ecl.js Ver.041208, Copyright (C) http://nurucom-archives.hp.infoseek.co.jp/digital/)

// Needed because seesaawiki (女优维基） search only accepts EUC-JP percent-encoded
// keywords; encodeURIComponent is UTF-8 only and returns zero results there.
// SUA_JCT8836 is the JIS X 0208 table (8836 chars), decoded from the compressed blob.
var suaEucJpEncode = function (str) {
    return str.replace(/[^*+.-9A-Z_a-z-]/g,function(s){
        var c=s.charCodeAt(0);
        return (c<128?(c<16?"%0":"%")+c.toString(16):65376<c&&c<65440?"%8E%"+(c-65216).toString(16):(c=SUA_JCT8836.indexOf(s))<0?"%A1%A6":"%"+((c-(c%=94))/94+161).toString(16)+"%"+(c+161).toString(16)).toUpperCase()
    })
};


