				return '<span data-act="hub-search-term" data-term="' + suaEsc(it.code || it.title || "") + '" title="' + t + '" style="flex:0 0 96px;cursor:pointer;text-align:center;font-size:11px;line-height:1.3;color:var(--fg)">' + cv + '<span style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + c + '</span></span>';
