		try { var _pg = suaHubPageEl(); var _ov2 = _pg ? _pg.querySelector("[data-hp-video]") : null; if (_ov2 && _ov2 !== video) _ov2.pause(); } catch (e4) {}
		if (srcEl) srcEl.textContent = "正在播放：" + site.name + " · 线路 1（" + stream.kind + "）";
