			date: String(row[SUA_LTX_IDX.date] || ""),
			maker: String(row[SUA_LTX_IDX.maker] || ""),
			actors: Array.isArray(row[SUA_LTX_IDX.actors]) ? row[SUA_LTX_IDX.actors] : [],
			cover: String(row[SUA_LTX_IDX.cover] || ""),
			score5: sc || "",
			score10: sc ? (Math.round(sc * 2 * 10) / 10) + "" : "",
			votes: Number(row[SUA_LTX_IDX.votes]) || 0,
			source: "LTX 4K",
			term: String(row[SUA_LTX_IDX.code] || "")
