	// v6.40.8：番号识图——AVScan 上传（POST https://avscan.cc/search，字段 file）。
	// 实测：返回 JSON {results:[{video_code, best_similarity, frames:[{image_name, similarity, thumb}]}]}；
	// 图片无效 400 {"detail":"invalid image"}；字段名错 422 提示缺 file。免费免登录。
	function suaAvScan(file) {
		return new Promise(function (resolve, reject) {
			var fd = null;
			try { fd = new FormData(); fd.append("file", file); } catch (e) { reject(new Error("图片读取失败")); return; }
			var done = function (text, status) {
				var data = null;
				try { data = JSON.parse(String(text || "")); } catch (e2) {}
				if (data && data.detail) { reject(new Error(typeof data.detail === "string" ? data.detail : "图片无效")); return; }
				if (status && status >= 400) { reject(new Error("HTTP " + status)); return; }
				if (!data) { reject(new Error("返回格式不对")); return; }
				var results = (data && data.results) || [];
				resolve(results);
			};
			if (typeof GM_xmlhttpRequest === "function") {
				try {
					GM_xmlhttpRequest({
						method: "POST", url: "https://avscan.cc/search", data: fd, timeout: 30000,
						onload: function (res) { done(res && res.responseText, res && res.status); },
						onerror: function () { reject(new Error("网络错误")); },
						ontimeout: function () { reject(new Error("请求超时")); }
					});
					return;
				} catch (e3) {}
			}
			try {
				fetch("https://avscan.cc/search", { method: "POST", body: fd }).then(function (res) {
					return res.text().then(function (t) { done(t, res.status); });
				}).catch(function () { reject(new Error("网络错误")); });
			} catch (e4) { reject(new Error("网络错误")); }
		});
	}
	// v6.40.8：识图入口——选图后上传识别，结果按相似度排成卡片，点卡片按番号搜。
	function suaAvScanRun(file) {
		var page = suaHubPageEl();
		if (!page) return;
		var grid = page.querySelector("[data-hp-grid]");
		if (!grid) return;
		if (!file) return;
		if (file.size > 8 * 1024 * 1024) { suaToast("图片太大（超过 8MB），换一张小的"); return; }
		grid.innerHTML = '<p class="hp-empty">正在识图…（AVScan，上传截图识别番号）</p>';
		suaAvScan(file).then(function (results) {
			if (!results || !results.length) {
				grid.innerHTML = '<p class="hp-empty">没认出来——换一张更清晰的截图（正脸 / 全身 / 关键画面）再试。</p>';
				return;
			}
			var html = '<p class="hp-group">识图结果 · 点卡片按番号搜（相似度越高越准）</p><div class="hp-vgrid">';
			results.slice(0, 6).forEach(function (r) {
				var frame = (r.frames && r.frames[0]) || {};
				var thumb = frame.thumb ? ("https://avscan.cc" + frame.thumb) : "";
				var when = "";
				try { var m = String(frame.image_name || "").match(/_(\d{2}-\d{2}-\d{2})\.jpg$/); if (m) when = m[1]; } catch (e) {}
				html += '<article class="hp-vcard" data-hp="term" data-val="' + suaEsc(r.video_code || "") + '">'
					+ (thumb ? '<img src="' + suaEsc(thumb) + '" alt="" loading="lazy">' : '<div class="hp-vcover">▶</div>')
					+ '<p class="hp-vtitle">' + suaEsc(r.video_code || "") + '</p>'
					+ '<p class="hp-vmeta">' + suaEsc("相似度 " + (r.best_similarity || 0) + "%" + (when ? " · " + when : "")) + '</p>'
					+ '<span class="hp-vsrc">AVScan 识图</span></article>';
			});
			grid.innerHTML = html + '</div>';
		}).catch(function (err) {
			grid.innerHTML = '<p class="hp-empty">识图失败（' + suaEsc((err && err.message) || "网络错误") + '）——稍后再试，或直接打开 avscan.cc 上传。</p>';
		});
	}
	// v6.40.0：女优/系列/片商索引——抓 JavDB 索引页（/actresses、/series、/makers），
	// 首页多三行，点一下按该名字搜片；抓不到（JavDB 被墙）显示“暂不可用”不报错。
	function suaHubIndex(kind) {
		var box = null;
		try { box = document.querySelector('[data-hp-index="' + kind + '"]'); } catch (error) {}
		if (!box) return;
		if (box.getAttribute("data-loaded") === "1") return;
		box.setAttribute("data-loaded", "1");
		var urls = { actress: "https://javdb.com/actresses", series: "https://javdb.com/series", maker: "https://javdb.com/makers" };
		var url = urls[kind] || "";
		if (!url) return;
		try {
			suaGmGet(url, 12000).then(function (html) {
				var items = [];
				try {
					var doc = new DOMParser().parseFromString(html, "text/html");
					var links = doc.querySelectorAll("a[href]");
					var seen = {};
					for (var i = 0; i < links.length && items.length < 24; i++) {
						var a = links[i];
						var href = a.getAttribute("href") || "";
						var name = (a.textContent || "").trim();
						if (!name || name.length > 24) continue;
						if (href.indexOf("/" + kind) !== 0 && href.indexOf("/actresses/") !== 0 && href.indexOf("/series/") !== 0 && href.indexOf("/makers/") !== 0) continue;
						if (seen[name]) continue;
						seen[name] = 1;
						var _abs28 = "";
						try { _abs28 = suaHlsAbs(href, "https://javdb.com/"); } catch (e) {}
						items.push({ name: name, url: _abs28 });
					}
				} catch (error) {}
				if (!items.length) { try { box.innerHTML = '<span class="hp-index-empty">暂不可用（JavDB 可能被墙）</span>'; } catch (error) {} return; }
				var html2 = "";
				for (var j = 0; j < items.length; j++) { html2 += '<span class="chip hp-index-chip" data-hp="browse" data-val="' + suaEsc(items[j].name) + '" data-url="' + suaEsc(items[j].url || "") + '">' + suaEsc(items[j].name) + "</span>"; }
				try { box.innerHTML = html2; } catch (error) {}
			}).catch(function () { try { box.innerHTML = '<span class="hp-index-empty">暂不可用（JavDB 可能被墙）</span>'; } catch (error) {} });
		} catch (error) { try { box.innerHTML = '<span class="hp-index-empty">暂不可用</span>'; } catch (error) {} }
	}
	// v6.40.1：聚合首页上下文感知——当前页面有番号/女优时，先显“当前影片”再显通用索引；
