					+ '<div class="ops">' + suaHubLineBtn(site, item) + (item && item.hit && site.group === "magnet" ? '<button class="btn small primary" data-act="magnet-play" data-site="' + suaEsc(site.id) + '">🧲 磁力播放</button>' : '') + '<button class="btn small primary" data-act="res-open" data-url="' + suaEsc(target) + '">' + (direct ? "打开资源页" : "打开搜索") + '</button>'
					+ (item && item.hit ? '<button class="btn small ghost" data-act="res-window" data-url="' + suaEsc(target) + '">新窗口播放</button>' : '')
					+ '</div></div>';
