		sua.hits = [];
		try { var ltxHit = suaLtxSubHit(code); if (ltxHit) sua.hits.push(ltxHit); } catch (e) {}
		suaRenderHits("正在搜迅雷 / SubtitleCat / AVSubtitles / 直链站…");
		var pending = 0;
