			try { var _eb = document.getElementById("sua-webfs-exit"); if (_eb && _eb.parentNode) _eb.parentNode.removeChild(_eb); } catch (error) {}
			if (!sua.miniBeforeFs) return;
			sua.miniBeforeFs = false;
