		for (var j = Math.max(0, cues.length - 20); j < cues.length; j++) tail += suaPlusOrig(cues[j]) + "\n";
		var sig = String(location.href || "").split("#")[0] + "|" + cues.length + "|" + (sua.video && sua.video.currentSrc ? sua.video.currentSrc : "") + "|" + (suaPlusCfg().target || "zh-CN");
		return "t" + cues.length + "_" + suaPlusHash(sig + "|" + head + "|" + tail);
