	function suaPlusApiBase() {
		var base = String(suaPlusCfg().aiBase || "").trim().replace(/\/+$/, "");
		if (!base) return "";
		base = base.replace(/\/chat\/completions$/i, "");
		if (/\/openai$/i.test(base)) return base;
		if (!/\/v\d+[a-z0-9.-]*$/i.test(base)) base += "/v1";
		return base;
	}
	function suaPlusPickFrom(list) {
		list = list || [];
		var pref = ["gpt-4o-mini", "gpt-4o", "gpt-4.1-mini", "deepseek-chat", "qwen-plus", "glm-4-flash", "claude-3-5-sonnet", "gpt-4"];
		for (var i = 0; i < pref.length; i++) {
			for (var j = 0; j < list.length; j++) {
				if (String(list[j]).toLowerCase().indexOf(pref[i]) >= 0) return list[j];
			}
		}
		return list[0] || "gpt-4o-mini";
	}
	function suaPlusPickModel(cfg) {
		cfg = cfg || suaPlusCfg();
		var model = String(cfg.aiModel || "").trim();
		if (model && model.toLowerCase() !== "auto") return model;
		if (cfg.autoModel) return cfg.autoModel;
		return suaPlusPickFrom(cfg.aiModels || []);
	}
	function suaPlusGet(url, headers) {
		if (typeof GM_xmlhttpRequest !== "function") {
			return fetch(url, { headers: headers || {}, credentials: "omit" }).then(function (res) {
				if (!res.ok) throw new Error("HTTP " + res.status);
				return res.text();
			});
		}
		return new Promise(function (resolve, reject) {
			GM_xmlhttpRequest({
				method: "GET", url: url, headers: headers || {}, timeout: 20000,
				onload: function (r) {
					if (r.status >= 200 && r.status < 300) resolve(r.responseText);
					else reject(new Error("HTTP " + r.status + " " + String(r.responseText || "").slice(0, 120)));
				},
				onerror: function () { reject(new Error("网络错误")); },
				ontimeout: function () { reject(new Error("超时")); }
			});
		});
	}
	function suaPlusFetchModels() {
		var cfg = suaPlusCfg();
		var base = suaPlusApiBase();
		if (!base) return suaToast("先填 API 地址");
		if (!cfg.aiKey) return suaToast("先填 API Key 再获取模型");
		suaPlusStatus("正在获取模型列表…");
		suaPlusGet(base + "/models", { "Authorization": "Bearer " + cfg.aiKey }).then(function (raw) {
			var data = JSON.parse(raw);
			var rows = data.data || data.models || data;
			if (!Array.isArray(rows)) rows = [];
			var list = rows.map(function (m) { return typeof m === "string" ? m : (m.id || m.name || ""); }).filter(Boolean);
			if (!list.length) throw new Error("接口没有返回模型列表");
			list.sort();
			var next = suaPlusCfg();
			next.aiModels = list;
			next.autoModel = suaPlusPickFrom(list);
			if (!next.aiModel || String(next.aiModel).toLowerCase() === "auto") next.aiModel = "auto";
			try { suaWrite(SUA_PLUS_KEY, next); } catch (error) {}
			suaToast("模型列表已更新（默认 " + next.autoModel + "）");
			suaPlusRender();
			suaPlusStatus("已获取 " + list.length + " 个模型，自动使用 " + next.autoModel);
		}).catch(function (err) {
			suaPlusStatus("获取模型失败：" + (err && err.message ? err.message : "网络问题"));
		});
	}
	function suaPlusFmt(sec) {
		sec = Math.max(0, Math.floor(Number(sec) || 0));
		var m = Math.floor(sec / 60), s2 = sec % 60;
		return (m < 10 ? "0" : "") + m + ":" + (s2 < 10 ? "0" : "") + s2;
	}
	function suaSeekPreview(target, delta) {
		if (!suaPlusCfg().seekPreview) return;
		var root = sua.ui && sua.ui.root;
		if (!root) return;
		var video = sua.video;
		var dur = video && isFinite(video.duration) ? video.duration : 0;
		var box = root.querySelector("[data-seek-preview]");
		if (!box) {
			box = document.createElement("div");
			box.setAttribute("data-seek-preview", "1");
			box.style.cssText = "position:fixed;left:50%;top:14%;transform:translateX(-50%);z-index:2147483001;background:rgba(10,12,16,.82);color:#fff;padding:10px 16px;border-radius:14px;font:600 14px/1.4 system-ui,-apple-system,sans-serif;text-align:center;pointer-events:none;display:none;min-width:160px;backdrop-filter:blur(6px)";
			box.innerHTML = '<img data-sp-img alt="" style="display:none;width:160px;height:90px;object-fit:cover;border-radius:8px;margin:0 auto 6px"><div data-sp-time></div><div style="height:3px;background:rgba(255,255,255,.25);border-radius:2px;margin-top:6px;overflow:hidden"><div data-sp-bar style="height:100%;width:0;background:#52a8ff"></div></div>';
			root.appendChild(box);
		}
		var img = box.querySelector("[data-sp-img]");
		var time = box.querySelector("[data-sp-time]");
		var bar = box.querySelector("[data-sp-bar]");
		time.textContent = suaPlusFmt(target) + (dur ? " / " + suaPlusFmt(dur) : "") + (delta ? (delta > 0 ? "  +" + Math.abs(delta) + "s" : "  -" + Math.abs(delta) + "s") : "");
		bar.style.width = dur ? Math.round(Math.min(100, Math.max(0, target / dur * 100))) + "%" : "0";
		var frame = null;
		try {
			var frames = sua.plusFrames || [];
			for (var i = 0; i < frames.length; i++) {
				if (!frame || Math.abs(frames[i].t - target) < Math.abs(frame.t - target)) frame = frames[i];
			}
		} catch (error) {}
		if (frame && frame.url) { img.src = frame.url; img.style.display = "block"; }
		else { img.style.display = "none"; }
		box.style.display = "block";
		window.clearTimeout(sua.spTimer);
		sua.spTimer = window.setTimeout(function () { box.style.display = "none"; }, 1100);
	}
